+/// Override the DP ranks a handshake-owned test config connects to.
+fn with_engine_range(
+    mut config: EngineCoreClientConfig,
+    start_index: u32,
+    dp_size: usize,
+) -> EngineCoreClientConfig {
+    let TransportMode::HandshakeOwner {
+        engine_start_index,
