+                }
+                out.ordinary(content.trim_matches(trim));
+                for call in message["tool_calls"].as_array().into_iter().flatten() {
+                    tool_call(out, call)?;
+                }
+            }
+            "tool" => {
+                let start = index;
+                while index + 1 < messages.len() && messages[index + 1]["role"] == "tool" {
+                    index += 1;
+                }
+                out.control("<|observation|>")?;
