+                    out,
+                    &messages[start..=index],
+                    start.checked_sub(1).map(|i| &messages[i]),
+                    tools,
+                    media,
+                )?;
+            }
+            _ => {}
+        }
+        index += 1;
+    }
+    if mode == GenerationPromptMode::StartNewAssistant {
+        out.control("<|assistant|><think>")?;
+    }
+    Ok(())
+}
